A view plugin can easily add a new menu entry into the burger menu using `addTitleBarMenuAction(WidgetAction* action)`:
```cpp
/// [DataPropertiesPlugin.h]

gui::TriggerAction* getAdditionalEditorAction() override { return &_additionalEditorAction; }
gui::TriggerAction      _additionalEditorAction;    /** Trigger action to start something*/

/// [DataPropertiesPlugin.cpp]

addTitleBarMenuAction(&_additionalEditorAction);
connect(&_additionalEditorAction, &TriggerAction::triggered, this, [this]() -> void {
    // open some new window or whatever
});
```

